    const refreshed = await updateDocument(document.id, tenantId, {
      blockchain: {
        txHash,
        blockHeight: anchor.blockNumber || 0,
        anchoredAt: anchor.anchoredAt || anchor.createdAt || new Date().toISOString(),
        network: anchor.network,
        status: 'confirmed',
        anchorId: bc.anchorId,
